## Classes
```cpp
class Account
{
public:
    explicit Account(int cents) : m_cents{ cents } {}   // ctor + init list
    ~Account() = default;                               // destructor
    Account(const Account&) = default;                  // copy ctor
    Account& operator=(const Account&) = default;       // copy assign
    Account(Account&&) noexcept = default;              // move ctor
    Account& operator=(Account&&) noexcept = default;   // move assign

    int cents() const { return m_cents; }                // const member fn
    static int count();                                  // static member fn
    friend std::ostream& operator<<(std::ostream&, const Account&);
    auto operator<=>(const Account&) const = default;
private:
    int m_cents{};
    static inline int s_count{ 0 };
};
```
→ [[6.01 Classes and Objects]] · [[6.02 Constructors]] · [[6.07 Operator Overloading Basics]] · [[7.05 Move Semantics]]

## Inheritance
```cpp
class Shape
{
public:
    virtual ~Shape() = default;
    virtual double area() const = 0;       // pure virtual → abstract
};
class Circle final : public Shape
{
public:
    double area() const override { return 3.14159 * r * r; }
private:
    double r{ 1 };
};
```
